/**
 * Highlight categories of token kinds (D94, R-LANG-1): the categories the generated TextMate,
 * Monarch and Lezer grammars use (they are the Lezer token names). Each diagram's
 * kind → category table is generated by tools/gen-grammar from its grammar file; the shared
 * kinds below are fixed here.
 */
import { Kind } from './tokens.js';
import type { TokenKind } from './tokens.js';

/** Every highlight category, in the order the highlighters declare them. */
export const TOKEN_CATEGORIES = [
  'Keyword',
  'String',
  'Operator',
  'Number',
  'Comment',
  'Punctuation',
  'Variable',
  'Constant',
  'Meta',
  'Function',
  'Other',
] as const;

/** A highlight category; `Other` is text the highlighters leave unstyled. */
export type TokenCategory = (typeof TOKEN_CATEGORIES)[number];

/** Categories of the shared {@link Kind}s, the same for every diagram. */
export const SHARED_CATEGORIES: Readonly<Record<TokenKind, TokenCategory>> =
  /* @__PURE__ */ Object.freeze({
    [Kind.EOF]: 'Other',
    [Kind.Newline]: 'Other',
    [Kind.Comment]: 'Comment',
    [Kind.Directive]: 'Meta',
    [Kind.Space]: 'Other',
    [Kind.Error]: 'Other',
  });

/**
 * A diagram's kind → category table: `byKey` names the category of every key of the diagram's
 * kind object (exactly those keys, checked by the compiler), merged over
 * {@link SHARED_CATEGORIES}. Generated per diagram by tools/gen-grammar.
 */
export function kindCategories<K extends string>(
  kinds: Readonly<Record<K, TokenKind>>,
  byKey: NoInfer<Readonly<Record<K, TokenCategory>>>
): Readonly<Record<TokenKind, TokenCategory>> {
  const out: Record<TokenKind, TokenCategory> = { ...SHARED_CATEGORIES };
  for (const k of Object.keys(byKey) as K[]) out[kinds[k]] = byKey[k];
  return Object.freeze(out);
}
